const D = { energy: .62, scale: 1, speed: 1, density: .5, aniso: .25, hue: 28, x: .5, y: .5, style: 'hele_shaw', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Hele-Shaw cell / Saffman-Taylor viscous fingering ------------------------------
// Air is injected into a viscous oil trapped in the thin gap between two glass plates.
// Darcy's law (v = -k/mu * grad p) makes the oil pressure HARMONIC, so the interface is
// Laplacian-growth unstable: any bump reaches into a steeper gradient, drinks more flux
// and runs away. Surface tension enters as a Gibbs-Thomson boundary condition
// p_interface = Pin - sigma*kappa, which starves high-curvature tips and so puts a floor
// under the finger width. The competition is the whole piece: fingers widen, tips split.
// ------------------------------------------------------------------------------------
const TAU = 6.283185307;
const BW = 148, BH = Math.max(64, Math.round(BW * height / width));
const N = BW * BH;
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH;
  S.PHI = new Float32Array(N); S.PH2 = new Float32Array(N); S.PR = new Float32Array(N);
  S.BC = new Float32Array(N); S.MSK = new Uint8Array(N); S.GRN = new Float32Array(N);
  S.TMP = new Float32Array(N);
  S.init = false;
}

const sd = P.seed | 0;
function hsh(ix, iy, iz) {
  let h = (Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(iz, 1274126177) + Math.imul(sd, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}

const PHI = S.PHI, PH2 = S.PH2, PR = S.PR, BC = S.BC, MSK = S.MSK, GRN = S.GRN, TMP = S.TMP;

// injection point drifts on incommensurate rates so no two cycles nucleate alike
const tt = K.t;
const cxN = Math.min(0.86, Math.max(0.14, P.x + 0.045 * Math.sin(tt * 0.037) + 0.02 * Math.sin(tt * 0.091 + 1.3)));
const cyN = Math.min(0.86, Math.max(0.14, P.y + 0.04 * Math.cos(tt * 0.051 + 0.7) + 0.018 * Math.sin(tt * 0.113)));

function reseed() {
  PHI.fill(0); PR.fill(0);
  const cn = (S.cno | 0);
  const cx = cxN * BW, cy = cyN * BH;
  const r0 = BH * 0.052;
  // seed-dependent angular harmonics: the nucleus is never a perfect disc, so the growth
  // has something to amplify (a perfect disc on a square grid just makes a grid-aligned star)
  const a1 = hsh(cn * 13 + 1, 7, 3) * TAU, a2 = hsh(cn * 13 + 2, 9, 3) * TAU, a3 = hsh(cn * 13 + 3, 11, 3) * TAU;
  const m1 = 3 + Math.floor(hsh(cn, 21, 5) * 4), m2 = 7 + Math.floor(hsh(cn, 23, 5) * 6);
  for (let j = 0; j < BH; j++) for (let i = 0; i < BW; i++) {
    const dx = i - cx, dy = j - cy, d = Math.sqrt(dx * dx + dy * dy);
    const th = Math.atan2(dy, dx);
    const rr = r0 * (1 + 0.20 * Math.sin(m1 * th + a1) + 0.11 * Math.sin(m2 * th + a2) + 0.07 * Math.sin(2 * th + a3));
    const v = 1 - Math.min(1, Math.max(0, (d - rr + 1.2) / 2.4));
    PHI[j * BW + i] = v * v * (3 - 2 * v);
  }
}
function buildGrain() {
  for (let j = 0; j < BH; j++) for (let i = 0; i < BW; i++) {
    // frozen plate grain — static, so it textures without flickering
    GRN[j * BW + i] = hsh(i, j, 91) * 0.6 + hsh(i >> 1, j >> 1, 92) * 0.4;
  }
}

if (!S.init || S.seedUsed !== P.seed) {
  S.init = true; S.seedUsed = P.seed; S.cno = 0; S.mode = 0; S.age = 0; S.cov = 0;
  buildGrain(); reseed();
}

// real-time accumulator: tolerates t0 resets (K.t can jump backwards at any time)
if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
let dt = K.t - S.lastT; S.lastT = K.t;
dt = dt < 0 ? 0 : (dt > 0.05 ? 0.05 : dt);

const sp = 0.4 + P.speed * 0.6;
// ---- dramaturgy: a coverage-driven inject / withdraw cycle (~50s at speed 1).
// Injection is the UNSTABLE direction and grows fingers; withdrawal (viscous pushing
// inviscid) is the stable one, so the front smooths as it retracts. Coverage-driven
// rather than timed means the front can never saturate the plate and freeze. ----
S.age += dt;
if (S.mode !== 1) {
  if (S.cov > 0.50 || S.age > 75 / sp) { S.mode = 1; S.age = 0; }
} else {
  if (S.cov < 0.012 || S.age > 40 / sp) { S.cno = (S.cno | 0) + 1; reseed(); S.mode = 0; S.age = 0; }
}
const growing = S.mode !== 1;

// ---- 1. smoothed phase field (curvature off the raw field is grid noise) + coverage ----
let cov = 0;
for (let j = 0; j < BH; j++) {
  const jm = (j > 0 ? j - 1 : 0) * BW, jp = (j < BH - 1 ? j + 1 : BH - 1) * BW, jc = j * BW;
  for (let i = 0; i < BW; i++) {
    const im = i > 0 ? i - 1 : 0, ip = i < BW - 1 ? i + 1 : BW - 1;
    PH2[jc + i] = PHI[jc + i] * 0.5 + (PHI[jc + im] + PHI[jc + ip] + PHI[jm + i] + PHI[jp + i]) * 0.125;
    if (PHI[jc + i] > 0.5) cov++;
  }
}
S.cov = cov / N;

// ---- 2. Gibbs-Thomson boundary values on the invaded phase ----
// density = finger COUNT: the selected wavelength goes like sqrt(sigma), so low tension
// shatters the front into many fine fingers, high tension keeps a few fat ones.
const sigma = 0.75 - P.density * 0.70;
for (let j = 0; j < BH; j++) {
  const jm = (j > 0 ? j - 1 : 0) * BW, jp = (j < BH - 1 ? j + 1 : BH - 1) * BW, jc = j * BW;
  for (let i = 0; i < BW; i++) {
    const im = i > 0 ? i - 1 : 0, ip = i < BW - 1 ? i + 1 : BW - 1, p = jc + i;
    if (PHI[p] < 0.5) { MSK[p] = 0; continue; }
    MSK[p] = 1;
    const c = PH2[p];
    const lap = PH2[jc + im] + PH2[jc + ip] + PH2[jm + i] + PH2[jp + i] - 4 * c;
    const gx = (PH2[jc + ip] - PH2[jc + im]) * 0.5, gy = (PH2[jp + i] - PH2[jm + i]) * 0.5;
    const gm = Math.sqrt(gx * gx + gy * gy);
    let kap = gm > 0.010 ? -lap / gm : 0;
    kap = kap < -1.4 ? -1.4 : (kap > 1.4 ? 1.4 : kap);
    BC[p] = 1 - sigma * kap;          // Pin = 1
  }
}

// ---- 3. relax the harmonic pressure in the oil (SOR, warm-started from last frame,
// so a handful of sweeps tracks the slowly-moving boundary). Borders stay 0 = the sink. ----
const wSOR = 1.75;
for (let it = 0; it < 14; it++) {
  for (let j = 1; j < BH - 1; j++) {
    const jm = (j - 1) * BW, jp = (j + 1) * BW, jc = j * BW;
    for (let i = 1; i < BW - 1; i++) {
      const p = jc + i;
      if (MSK[p]) { PR[p] = BC[p]; continue; }
      const nb = 0.25 * (PR[p - 1] + PR[p + 1] + PR[jm + i] + PR[jp + i]);
      PR[p] = PR[p] + wSOR * (nb - PR[p]);
    }
  }
}

// ---- 4. advance the interface at the Darcy flux ----
const aniso = P.aniso;
const mfold = 6;
const arot = tt * 0.019 + (S.cno | 0) * 0.7;     // the crystal axis creeps: never a repeat
// NOTE both branches read neighbours from TMP (a snapshot taken before the sweep) and write
// PHI. Updating PHI in place would let a cell see its already-updated left/up neighbour, which
// cascades the update across a whole row in one sweep — a runaway diffusion, and a systematic
// growth bias toward +x/+y.
TMP.set(PHI);
if (growing) {
  const gr = dt * 34 * sp * (0.62 + P.energy * 0.70) * (0.85 + K.swell * 0.18 + A.bass * 0.35);
  for (let j = 3; j < BH - 3; j++) {
    const jm = (j - 1) * BW, jp = (j + 1) * BW, jc = j * BW;
    for (let i = 3; i < BW - 3; i++) {
      const p = jc + i;
      if (TMP[p] >= 0.999) continue;
      const nbf = 0.25 * (TMP[p - 1] + TMP[p + 1] + TMP[jm + i] + TMP[jp + i]);
      if (nbf < 0.012) continue;
      const gx = (PR[p + 1] - PR[p - 1]) * 0.5, gy = (PR[jp + i] - PR[jm + i]) * 0.5;
      let gm = Math.sqrt(gx * gx + gy * gy);
      if (aniso > 0.001) {
        const th = Math.atan2(gy, gx);
        gm *= Math.max(0.05, 1 + aniso * 0.9 * Math.cos(mfold * (th - arot)));
      }
      const nv = TMP[p] + gr * gm * nbf;
      PHI[p] = nv > 1 ? 1 : nv;
    }
  }
} else {
  // Withdrawal: suck the air back out. Viscous-pushing-inviscid is the STABLE direction, so
  // the front does not finger — it recedes at its normal and relaxes its curvature, and the
  // fingers (which are all interface) are the first thing to go.
  // This is level-set normal motion, d(phi)/dt = -V*|grad phi|: the erosion is keyed on the
  // GRADIENT, so it only bites where an interface actually is. A value-keyed term instead
  // eats the whole interior at once the moment it dips below 1.
  const Vret = dt * 2.6 * sp;
  for (let j = 0; j < BH; j++) {
    const jm = (j > 0 ? j - 1 : 0) * BW, jp = (j < BH - 1 ? j + 1 : BH - 1) * BW, jc = j * BW;
    for (let i = 0; i < BW; i++) {
      const im = i > 0 ? i - 1 : 0, ip = i < BW - 1 ? i + 1 : BW - 1, p = jc + i;
      const sm = TMP[p] * 0.84 + (TMP[jc + im] + TMP[jc + ip] + TMP[jm + i] + TMP[jp + i]) * 0.04;
      const gx = (TMP[jc + ip] - TMP[jc + im]) * 0.5, gy = (TMP[jp + i] - TMP[jm + i]) * 0.5;
      const gm = Math.sqrt(gx * gx + gy * gy);
      const nv = sm - Vret * gm;
      PHI[p] = nv < 0 ? 0 : nv;
    }
  }
}

// ---- render ----
const g = S.g; g.loadPixels(); const px = g.pixels;
const sec = K.section | 0;
const style = P.style;
const hb = ((P.hue + Math.sin(tt * 0.021) * 10 + sec * 5) % 360 + 360) % 360;
function pal(m, sp2, off) {
  const hr = hb / 360 + off;
  return [0.5 + 0.5 * Math.cos(TAU * (m + hr)), 0.5 + 0.5 * Math.cos(TAU * (m + hr + sp2)), 0.5 + 0.5 * Math.cos(TAU * (m + hr + sp2 * 2))];
}
const cIn = pal(0.02, 0.16, 0.0);      // the injected phase
const cOil = pal(0.55, 0.10, 0.0);     // the defending viscous phase
const en = P.energy;
const glow = (0.5 + en * 1.5) * (0.85 + A.treble * 0.4);
// fringe families drift on their own clock: a motion floor that survives even a frozen front
const fdr = tt * 0.27 + Math.sin(tt * 0.083) * 1.4;
const nb2 = 5 + en * 12;

for (let j = 0; j < BH; j++) {
  const jm = (j > 0 ? j - 1 : 0) * BW, jp = (j < BH - 1 ? j + 1 : BH - 1) * BW, jc = j * BW;
  for (let i = 0; i < BW; i++) {
    const im = i > 0 ? i - 1 : 0, ip = i < BW - 1 ? i + 1 : BW - 1, p = jc + i;
    const ph = PH2[p], pr = PR[p], gn = GRN[p];
    const rim = 4 * ph * (1 - ph);                       // peaks exactly on the interface
    const dgx = (PR[jc + ip] - PR[jc + im]) * 0.5, dgy = (PR[jp + i] - PR[jm + i]) * 0.5;
    const act = Math.sqrt(dgx * dgx + dgy * dgy) * (1 - ph);   // Darcy flux — brightest at live tips
    let r, gg, b;
    if (style === 'interferogram') {
      const fr = 0.5 + 0.5 * Math.cos(pr * TAU * (nb2 * 1.6) + fdr);
      const cc = pal(pr * 0.85 + 0.1, 0.31, 0.0);
      const v = 0.30 + fr * 0.34;
      r = v * (0.5 + cc[0]); gg = v * (0.5 + cc[1]); b = v * (0.5 + cc[2]);
      const w = ph * 0.55;                                // the bubble reads as a fringe dislocation
      r = r * (1 - w) + 0.86 * w; gg = gg * (1 - w) + 0.83 * w; b = b * (1 - w) + 0.72 * w;
      r += act * glow * 1.4; gg += act * glow * 1.2; b += act * glow * 0.7;
    } else if (style === 'ink_plate') {
      const stip = (gn - 0.5) * 0.20;
      const ink = 0.13 + stip * 0.5 + 0.04 * Math.cos(pr * TAU * nb2 * 0.5 + fdr * 0.4);
      const paper = 0.80 + stip;
      let v = ink + (paper - ink) * ph;
      v -= rim * 0.30;                                   // a bitten litho edge
      v += act * glow * 0.5;
      r = v * 1.00; gg = v * 0.975; b = v * 0.93;
    } else if (style === 'metallic') {
      // form from light only: the pressure gradient is the surface normal
      const sh2 = Math.max(0, -(dgx * 0.62 + dgy * 0.78) * 26);
      const v = 0.16 + gn * 0.05 + sh2 * (0.5 + en) * 0.5;
      const inv = 0.30 + rim * 0.55 + gn * 0.06;
      let m = v * (1 - ph) + inv * ph;
      m += act * glow * 2.0;
      r = m * (0.80 + cIn[0] * 0.30); gg = m * (0.86 + cIn[1] * 0.24); b = m * (1.02 + cIn[2] * 0.16);
    } else if (style === 'thermal') {
      const m = Math.min(1, (act * 34 + rim * 0.55 + ph * 0.30) * (0.5 + en * 1.1) + 0.06 + gn * 0.03);
      r = Math.min(1, m * 2.15);
      gg = Math.min(1, Math.max(0, m * 2.0 - 0.55));
      b = Math.min(1, Math.max(0, m * 3.1 - 2.05) + Math.max(0, 0.40 - m * 1.5));
    } else {                                              // hele_shaw (default)
      const band = 0.5 + 0.5 * Math.cos(pr * TAU * nb2 + fdr);
      const ov = 0.17 + band * 0.085 + gn * 0.055;        // oil: never a flat fill
      const iv = 0.52 + gn * 0.07 + rim * 0.14;
      const mo = ov, mi = iv;
      const m = mo + (mi - mo) * ph;
      r = m * (0.62 + cIn[0] * 0.95) + cOil[0] * (1 - ph) * 0.10;
      gg = m * (0.52 + cIn[1] * 0.85) + cOil[1] * (1 - ph) * 0.11;
      b = m * (0.46 + cIn[2] * 0.70) + cOil[2] * (1 - ph) * 0.16;
      const tip = act * glow * 2.6;
      r += tip * 1.0; gg += tip * 0.86; b += tip * 0.55;
    }
    const o = 4 * p;
    px[o] = r < 0 ? 0 : (r > 1 ? 255 : r * 255);
    px[o + 1] = gg < 0 ? 0 : (gg > 1 ? 255 : gg * 255);
    px[o + 2] = b < 0 ? 0 : (b > 1 ? 255 : b * 255);
    px[o + 3] = 255;
  }
}
g.updatePixels();

const z = Math.max(1, P.scale);
const sw = BW / z, sh = BH / z;
const sx = Math.min(BW - sw, Math.max(0, cxN * BW - sw / 2));
const sy = Math.min(BH - sh, Math.max(0, cyN * BH - sh / 2));
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height, sx, sy, sw, sh);
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
